def algorithm(N):
    binary = bin(N)[2:]
    for _ in range(2):
        s = sum(int(digit) for digit in binary)
        binary += str(s % 2)
    return int(binary, 2)

for N in range(1, 100):
    R = algorithm(N)
    if R > 75:
        print(f"Ответ: {N}")  # 84
        break
